function ArticleSuppliersEditor({articleId,suppliers}){const[selected,setSelected]=useState([]),[preferred,setPreferred]=useState(''),[message,setMessage]=useState('');useEffect(()=>{let active=true;fetch('/api/catalog/'+articleId+'/suppliers',{credentials:'same-origin'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{if(active){setSelected((d.suppliers||[]).map(x=>x.id));setPreferred((d.suppliers||[]).find(x=>x.preferred)?.id||'')}}).catch(()=>{if(active)setMessage('Gekoppelde leveranciers niet beschikbaar.')});return()=>{active=false}},[articleId]);const save=async()=>{const r=await fetch('/api/catalog/'+articleId+'/suppliers',{method:'PUT',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({supplierIds:selected,preferredSupplierId:preferred})});setMessage(r.ok?'Leverancierskoppelingen bewaard.':'Leverancierskoppelingen bewaren mislukt.')};return <section className="assignment-editor"><b>Leveranciers gekoppeld aan dit artikel</b>{suppliers.map(x=><label className="toggle" key={x.id}><input type="checkbox" checked={selected.includes(x.id)} onChange={e=>setSelected(xs=>e.target.checked?[...xs,x.id]:xs.filter(id=>id!==x.id))}/>{x.name} · {x.enterprise_number||'geen KBO-nummer'}</label>)}<label>Voorkeursleverancier<select value={preferred} onChange={e=>setPreferred(e.target.value)}><option value="">Geen voorkeursleverancier</option>{suppliers.filter(x=>selected.includes(x.id)).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><button onClick={save}>Leveranciers bewaren</button>{message&&<small>{message}</small>}</section>}
function SupplierImageEditor({supplier,onSaved}){const[query,setQuery]=useState(supplier.name);const[busy,setBusy]=useState(false),[message,setMessage]=useState('');return <div className="supplier-image-editor"><input value={query} onChange={e=>setQuery(e.target.value)} aria-label="Zoekterm leveranciersafbeelding"/><button disabled={busy||!query.trim()} onClick={async()=>{setBusy(true);const r=await fetch('/api/images/import',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({kind:'supplier',entityId:supplier.id,query})});const d=await r.json();setBusy(false);if(!r.ok){setMessage(d.error||'Afbeelding importeren mislukt.');return}onSaved(d.imageUrl);setMessage('Afbeelding opgeslagen in '+d.storage+'.')}}>{busy?'Bezig…':'Zoek afbeelding'}</button>{message&&<small>{message}</small>}</div>}
function TeamMembersEditor({team,users}){const[members,setMembers]=useState([]),[selected,setSelected]=useState([]),[message,setMessage]=useState('');useEffect(()=>{let active=true;fetch('/api/teams/'+team.id+'/members',{credentials:'same-origin'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{if(active){const ids=(d.members||[]).map(x=>x.user_id);setMembers(d.members||[]);setSelected(ids)}}).catch(()=>{if(active)setMessage('Ledenlijst niet beschikbaar.')});return()=>{active=false}},[team.id]);const save=async()=>{const r=await fetch('/api/teams/'+team.id+'/members',{method:'PUT',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({members:selected.map(userId=>({userId,memberRole:'member'}))})});setMessage(r.ok?'Teamleden bewaard.':'Teamleden bewaren mislukt.')};return <div className="assignment-editor"><b>Teamleden</b>{users.filter(u=>u.active).map(u=><label className="toggle" key={u.id}><input type="checkbox" checked={selected.includes(u.id)} onChange={e=>setSelected(xs=>e.target.checked?[...xs,u.id]:xs.filter(x=>x!==u.id))}/>{u.name} · {u.email}</label>)}<button onClick={save}>Leden bewaren</button>{message&&<small>{message}</small>}</div>}
function BuyerAssignmentsEditor({user,categories}){const[assignments,setAssignments]=useState([]),[campus,setCampus]=useState('Ninove'),[category,setCategory]=useState(categories[0]||'Algemeen'),[message,setMessage]=useState('');useEffect(()=>{let active=true;fetch('/api/users/'+user.id+'/assignments',{credentials:'same-origin'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{if(active)setAssignments(d.assignments||[])}).catch(()=>{if(active)setMessage('Toewijzingen niet beschikbaar.')});return()=>{active=false}},[user.id]);const save=async(next)=>{const r=await fetch('/api/users/'+user.id+'/assignments',{method:'PUT',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({assignments:next})});if(r.ok){setAssignments(next);setMessage('Aankopersrechten bewaard.')}else setMessage('Aankopersrechten bewaren mislukt.')};return <div className="assignment-editor"><b>Toegewezen campus en categorie</b><div className="form-row"><select value={campus} onChange={e=>setCampus(e.target.value)}><option>Ninove</option><option>Zottegem</option><option>Beide campussen</option></select><select value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c}>{c}</option>)}</select><button onClick={()=>save([...assignments,{campus,category}].filter((a,i,x)=>x.findIndex(y=>y.campus===a.campus&&y.category===a.category)===i))}>Toewijzen</button></div>{assignments.map((a,i)=><div className="item" key={i}><span>{a.campus} · {a.category}</span><button onClick={()=>save(assignments.filter((_,j)=>j!==i))}>Verwijderen</button></div>)}{message&&<small>{message}</small>}</div>}
function OrderCard({order,onOpen}){return <article className="order clickable" onClick={onOpen}><b>{order.id} · {order.title}</b><span>{order.campus}{order.teamName?' · '+order.teamName:''} · {order.status}</span><p>{order.items.map(i=>i.name+' × '+i.qty).join(', ')}</p><small>{new Date(order.createdAt).toLocaleDateString('nl-BE')} · {order.requester}</small><button onClick={e=>{e.stopPropagation();onOpen()}}>Details <ChevronRight size={13}/></button></article>}
function OrderDetail({order,purchases,onStatus,onReorder,role,allowReorder}){const ps=purchases.filter(p=>order.items.some(i=>i.id===p.orderItemId));return <><article className="panel"><h2>{order.id} · {order.title}</h2><p>{order.campus}{order.teamName?' · '+order.teamName:''} · ingediend op {new Date(order.createdAt).toLocaleString('nl-BE')}</p>{role==='buyer'||role==='admin'?<label>Status<select value={order.status} onChange={e=>onStatus(e.target.value)}>{statuses.map(s=><option key={s}>{s}</option>)}</select></label>:<p>Status: <b>{order.status}</b></p>}<h3>Bestelregels</h3>{order.items.map(i=><div className="item" key={i.id}><span><b>{i.name} × {i.qty} {i.unit}</b><small>{i.eanCode?'EAN: '+i.eanCode+' · ':''}{i.justification}{i.suppliers?.length?' · Voorgestelde leveranciers: '+i.suppliers.map(x=>x.name).join(', '):''}</small></span></div>)}{order.motivation&&<p>Motivatie: {order.motivation}</p>}{order.remarks&&<p>Opmerkingen: {order.remarks}</p>}{allowReorder&&<button onClick={onReorder}>Herbestellen</button>}{role==='staff'&&['Ingediend','In behandeling'].includes(order.status)&&<button onClick={()=>onStatus('Geannuleerd')}>Bestelling annuleren</button>}<OrderCommunication orderId={order.id} items={order.items} role={role}/><OrderTimeline orderId={order.id}/></article><h2>Geregistreerde aankopen</h2>{ps.length?ps.map(p=><PurchaseCard key={p.id} purchase={p} readOnly/>):<article className="empty">Nog geen aankoop gekoppeld.</article>}</>}
function OrderCommunication({orderId,items,role}){const[requests,setRequests]=useState([]),[itemId,setItemId]=useState(items[0]?.id||''),[question,setQuestion]=useState(''),[answer,setAnswer]=useState({}),[error,setError]=useState('');const load=()=>fetch('/api/orders/'+orderId+'/information-requests',{credentials:'same-origin'}).then(async r=>{if(!r.ok)throw new Error('Communicatie niet beschikbaar.');return r.json()}).then(d=>setRequests(d.requests||[])).catch(e=>setError(e.message));useEffect(()=>{load()},[orderId]);const ask=async()=>{const r=await fetch('/api/orders/'+orderId+'/information-requests',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({orderItemId:itemId,question})});if(!r.ok){const d=await r.json();setError(d.error||'Vraag versturen mislukt.');return}setQuestion('');load()};const reply=async id=>{const r=await fetch('/api/information-requests/'+id+'/respond',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({answer:answer[id]||''})});if(!r.ok){const d=await r.json();setError(d.error||'Antwoord versturen mislukt.');return}setAnswer(x=>({...x,[id]:''}));load()};return <section className="communication"><h3>Informatieverzoeken</h3>{error&&<small className="error">{error}</small>}{requests.map(r=><div className="communication-item" key={r.id}><b>Vraag van {r.requester_name}</b><p>{r.request_text}</p>{r.response_text?<p className="response"><b>Antwoord</b><br/>{r.response_text}</p>:role==='staff'||role==='admin'?<><textarea value={answer[r.id]||''} onChange={e=>setAnswer(x=>({...x,[r.id]:e.target.value}))} placeholder="Antwoord op de vraag"/><button onClick={()=>reply(r.id)}>Antwoord versturen</button></>:<small>Wacht op antwoord van de aanvrager.</small>}</div>)}{(role==='buyer'||role==='admin')&&<div className="ask-question"><label>Bestelregel<select value={itemId} onChange={e=>setItemId(e.target.value)}>{items.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></label><label>Vraag aan de aanvrager<textarea value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Welke informatie ontbreekt?"/></label><button onClick={ask} disabled={!itemId||!question.trim()}>Informatie opvragen</button></div>}</section>}
function OrderTimeline({orderId}){const[events,setEvents]=useState([]),[error,setError]=useState('');useEffect(()=>{let active=true;fetch('/api/orders/'+orderId+'/events',{credentials:'same-origin'}).then(async r=>{if(!r.ok)throw new Error('Historiek niet beschikbaar voor dit account.');return r.json()}).then(d=>{if(active)setEvents(d.events||[])}).catch(e=>{if(active)setError(e.message)});return()=>{active=false}},[orderId]);return <section className="timeline"><h3>Chronologisch logboek</h3>{error?<small>{error}</small>:events.length?events.map(e=><div className="timeline-event" key={e.id}><b>{e.message||e.event_type}</b><small>{e.actor_name||'Systeem'} · {new Date(e.created_at).toLocaleString('nl-BE')}</small></div>):<small>Nog geen historiek beschikbaar.</small>}</section>}
function PurchaseCard({purchase,onChange,readOnly=false}){return <article className="order"><b>{purchase.itemName}</b><span>{purchase.status}</span><p>{purchase.orderId} · {purchase.campus} · {purchase.supplier}</p><p>Bestelbonnummer: <b>{purchase.number||'Niet ingevuld'}</b> · Besteldatum: {new Date(purchase.date+'T00:00:00').toLocaleDateString('nl-BE')}</p>{purchase.note&&<p>{purchase.note}</p>}{!readOnly&&<label>Status opvolgen<select value={purchase.status} onChange={e=>onChange({status:e.target.value})}>{purchaseStatuses.map(s=><option key={s}>{s}</option>)}</select></label>}</article>}
createRoot(document.getElementById('root')).render(<App/>);
